/** Source: battle_controller_player.c → Task_GiveExpToMon */
export const Task_GiveExpToMon: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let monId = (task.data[0]);
      let battler = task.data[2];
      let gainedExp = task.data[1];

      if (IsDoubleBattle() == true || monId != gBattlerPartyIndexes[battler])  
      {
          let mon: any = gPlayerParty[monId];
          let species = GetMonData(mon, MON_DATA_SPECIES);
          let level = GetMonData(mon, MON_DATA_LEVEL);
          let currExp = GetMonData(mon, MON_DATA_EXP);
          let nextLvlExp = gExperienceTables[gSpeciesInfo[species].growthRate][level + 1];

          if (currExp + gainedExp >= nextLvlExp)
          {
              let savedActiveBattler = 0;

              SetMonData(mon, MON_DATA_EXP, nextLvlExp);
              CalculateMonStats(mon);
              gainedExp -= nextLvlExp - currExp;
              savedActiveBattler = gActiveBattler;
              gActiveBattler = battler;
              BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, RET_VALUE_LEVELED_UP, gainedExp);
              gActiveBattler = savedActiveBattler;

              if (IsDoubleBattle() == true
               && ((monId) == gBattlerPartyIndexes[battler] || (monId) == gBattlerPartyIndexes[BATTLE_PARTNER(battler)]))
                  task.func = (t) => Task_LaunchLvlUpAnim(t, rt);
              else
                  task.func = (t) => DestroyExpTaskAndCompleteOnInactiveTextPrinter(t, rt);
          }
          else
          {
              currExp += gainedExp;
              SetMonData(mon, MON_DATA_EXP, currExp);
              gBattlerControllerFuncs[battler] = CompleteOnInactiveTextPrinter;
              rt.DestroyTask(taskId);
          }
      }
      else
      {
          task.func = (t) => Task_PrepareToGiveExpWithExpBar(t, rt);
      }
};

